<?php require __DIR__.'/../config/bootstrap.php';admin_required();$s=settings($pdo);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf($_POST['csrf']??'');foreach(['business_name','phone','email','notification_email','privacy_url'] as $k){$q=$pdo->prepare("INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$q->execute([$k,trim($_POST[$k]??'')]);}$s=settings($pdo);$msg='Settings saved.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings</title><link rel="stylesheet" href="admin.css"></head><body><div class="shell"><aside><div class="mark">R+</div><a href="dashboard.php">Dashboard</a><a href="promotion.php">Promotion</a><a href="leads.php">Leads</a><a href="settings.php">Settings</a><a href="logout.php">Logout</a></aside><main><div class="head"><div><small>CONFIGURATION</small><h1>Settings</h1></div></div><section class="panel form"><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Business name<input name="business_name" value="<?=e($s['business_name']??'Renova+')?>" required></label><label>Phone<input name="phone" value="<?=e($s['phone']??'')?>"></label><label>Public email<input name="email" value="<?=e($s['email']??'')?>"></label><label>Notification email<input name="notification_email" value="<?=e($s['notification_email']??'')?>"></label><label>Privacy policy URL<input name="privacy_url" value="<?=e($s['privacy_url']??'#privacy')?>"></label><button>Save settings</button></form></section></main></div></body></html>
